Repair the following GNU C++17 code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
Today is the final contest of INOI (Iranian National Olympiad in Informatics). The contest room is a row with $$$n$$$ computers. All computers are numbered with integers from $$$1$$$ to $$$n$$$ from left to right. There are $$$m$$$ participants, numbered with integers from $$$1$$$ to $$$m$$$.We have an array $$$a$$$ of length $$$m$$$ where $$$a_{i}$$$ ($$$1 \leq a_i \leq n$$$) is the computer behind which the $$$i$$$-th participant wants to sit.Also, we have another array $$$b$$$ of length $$$m$$$ consisting of characters 'L' and 'R'. $$$b_i$$$ is the side from which the $$$i$$$-th participant enters the room. 'L' means the participant enters from the left of computer $$$1$$$ and goes from left to right, and 'R' means the participant enters from the right of computer $$$n$$$ and goes from right to left.The participants in the order from $$$1$$$ to $$$m$$$ enter the room one by one. The $$$i$$$-th of them enters the contest room in the direction $$$b_i$$$ and goes to sit behind the $$$a_i$$$-th computer. If it is occupied he keeps walking in his direction until he reaches the first unoccupied computer. After that, he sits behind it. If he doesn't find any computer he gets upset and gives up on the contest.The madness of the $$$i$$$-th participant is the distance between his assigned computer ($$$a_i$$$) and the computer he ends up sitting behind. The distance between computers $$$i$$$ and $$$j$$$ is equal to $$$|i - j|$$$.The values in the array $$$a$$$ can be equal. There exist $$$n^m \cdot 2^m$$$ possible pairs of arrays $$$(a, b)$$$.Consider all pairs of arrays $$$(a, b)$$$ such that no person becomes upset. For each of them let's calculate the sum of participants madnesses. Find the sum of all these values.You will be given some prime modulo $$$p$$$. Find this sum by modulo $$$p$$$.
</problem_description>

Here is the GNU C++17 code you have to repair:
<original_code>
#include <bits/stdc++.h>

using namespace std;
#define int long long
const int maxn=505;
int p;
int po(int a,int b)
{
    if(b==0) return 1;
    if(b==1) return a;
    if(b%2==0)
    {
        int u=po(a,b/2);
        return (u*u)%p;
    }
    else
    {
        int u=po(a,b-1);
        return (a*u)%p;
    }
}
int fact[maxn];
int invf[maxn];
int c3[maxn][maxn];
int c(int n,int k)
{
    return c3[n][k];
}
int32_t main()
{
    ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);
    int n,m;
    cin>>n>>m;
    cin>>p;
    int u1=1;
    for(int i=0;i<maxn;++i)
    {
        fact[i]=u1;
        invf[i]=inv(fact[i]);
        u1*=(i+1);
        u1%=p;
    }
    for(int i=0;i<maxn;++i)
    {
        for(int j=0;j<maxn;++j)
        {
            if(i>j) c3[i][j]=c3[i-1][j-1]+c3[i-1][j];
            else if(i==j) c3[i][j]=1;
        }
    }
    int dp1[n+1];
    dp1[0]=1;
    int dp2[n+1];
    dp2[0]=0;
    for(int i=1;i<=n;++i)
    {
        dp1[i]=0;
        dp2[i]=0;
        for(int j=0;j<i;++j)
        {
            dp1[i]+=(((((dp1[j]*dp1[i-1-j])%p)*(i+1))%p)%p)*c(i-1,j);
            dp2[i]+=((((((dp1[j]*dp2[i-j-1])%p)*(i+1)+((dp2[j]*dp1[i-j-1])%p)*(i+1)+((dp1[j]*dp1[i-1-j])%p)*((((i-1-j)*(i-j)+j*(j+1))/2)%p))%p)%p)%p)*c(i-1,j);
            dp2[i]%=p;
            dp1[i]%=p;
            //cout<<dp1[i]<<" "<<dp2[i]<<endl;
        }
    }
    //cout<<dp2[2]<<endl;
    int dp3[n+1][m+1];
    int dp4[n+1][m+1];
    for(int i=0;i<=n;++i)
    {
        for(int j=0;j<=m;++j)
        {
            dp3[i][j]=0;
            dp4[i][j]=0;
        }
    }
    for(int i=0;i<=n;++i)
    {
        for(int j=0;j<=i;++j)
        {
            for(int k=0;k<=j;++k)
            {
                 if(k!=j)
                 dp3[i][j]+=((dp3[i-k-1][j-k]*dp1[k])%p)*c(j,k);
                 else
                 dp3[i][j]+=dp1[k];
                 dp3[i][j]%=p;
                 if(k!=j)
                 dp4[i][j]+=((dp4[i-k-1][j-k]*dp1[k]+dp2[k]*dp3[i-k-1][j-k])%p)*c(j,k);
                 else
                 dp4[i][j]+=dp2[k];
                 dp4[i][j]%=p;
            }
        }
    }
    cout<<dp4[n][m];
    return 0;
}

